1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Emits an audit line on the dedicated {@code AUDIT} logger recording the newly created
10	 * owner's id, customer code, registration date, membership level and membership number.
11	 * Runs after the owner has been saved so the generated id is available.
12	 */
13	public class AuditOwnerCreated {
14	
15	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
16	
17	    public void service(@Val Owner owner) {
18	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
19	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
20	                owner.getMembershipLevel(), owner.getMembershipNumber());
21	    }
22	}
