1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.CityRegions;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.model.OwnerTelephones;
13	import org.springframework.samples.petclinic.repository.OwnerRepository;
14	
15	/**
16	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is
17	 * the region derived from the postcode by the shared {@link CityRegions} table (or {@code UNKNOWN}
18	 * when the postcode is absent or in no known range) and HASH8 is the first 8 upper-case hex
19	 * characters of SHA-256 over {@code normalizedTelephone + lastName} (e.g. {@code NSW-3A7F1C2D}).
20	 * The telephone is normalized to E.164 via {@link OwnerTelephones} so the hash is stable regardless
21	 * of the incoming format.
22	 *
23	 * <p>The base code is fully determined by the owner's own fields, but two distinct owners could in
24	 * principle hash to the same code. When the computed code collides with an existing owner's
25	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes
26	 * it unique, so distinct owners always end up with distinct customer codes.
27	 */
28	public class AssignCustomerCode {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String region = CityRegions.identityRegion(owner.getPostcode());
32	        String normalizedTelephone = OwnerTelephones.toE164OrRaw(owner.getTelephone());
33	        String hash8 = hash8(normalizedTelephone + owner.getLastName());
34	        String baseCode = region + "-" + hash8;
35	
36	        Set<String> existingCodes = new HashSet<>();
37	        for (Owner existing : ownerRepository.findAll()) {
38	            String code = existing.getCustomerCode();
39	            if (code != null) {
40	                existingCodes.add(code);
41	            }
42	        }
43	
44	        String code = baseCode;
45	        for (int n = 2; existingCodes.contains(code); n++) {
46	            code = baseCode + "-" + n;
47	        }
48	        owner.setCustomerCode(code);
49	    }
50	
51	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
52	    private static String hash8(String value) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest(value.getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder(8);
57	            for (byte b : digest) {
58	                sb.append(String.format("%02X", b));
59	                if (sb.length() >= 8) {
60	                    break;
61	                }
62	            }
63	            return sb.substring(0, 8);
64	        }
65	        catch (NoSuchAlgorithmException ex) {
66	            // SHA-256 is a required algorithm on every JVM, so this cannot happen in practice.
67	            throw new IllegalStateException("SHA-256 not available", ex);
68	        }
69	    }
70	}
