1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.FiscalYear;
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>}
9	 * where YY is the last two digits of the fiscal year containing the business-day-adjusted
10	 * registrationDate (e.g. {@code NSW-3A7F1C2D-M26}). Runs after the customer code and
11	 * registration date have been assigned, so both are available.
12	 */
13	public class AssignMembershipNumber {
14	
15	    public void service(@Val Owner owner) {
16	        String yy = String.format("%02d", FiscalYear.endingYearOf(owner.getRegistrationDate()) % 100);
17	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
18	    }
19	}
