1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Caps the new owner's {@code membershipLevel} at one above the current maximum
9	 * membershipLevel among their existing household members (those sharing the owner's
10	 * {@code householdId} — see {@link OwnerHousehold}). Runs after {@link AssignMembership}
11	 * has derived the level and before the owner is saved, so the scan of existing members
12	 * excludes the owner being created.
13	 *
14	 * <p>When the household has no existing member with a level, no cap applies and the
15	 * derived level stands. Otherwise the level is lowered to {@code max + 1} whenever the
16	 * derived level would exceed it; a level already at or below the ceiling is left as is.
17	 */
18	public class CapMembershipLevel {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        Integer level = owner.getMembershipLevel();
22	        if (level == null) {
23	            return;
24	        }
25	        Integer maxExisting = OwnerHousehold.maxMembershipLevel(owner.getHouseholdId(),
26	                ownerRepository.findAll());
27	        if (maxExisting != null && level > maxExisting + 1) {
28	            owner.setMembershipLevel(maxExisting + 1);
29	        }
30	    }
31	}
