1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Hashing;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * The single definition of household identity, used by {@link AssignOwnerHousehold} (which
10	 * stamps the householdId) and by the household-keyed rules (household size, membership-level
11	 * ceiling), so the rule lives in one place. Duplicate detection is keyed on the identityKey,
12	 * not the householdId.
13	 *
14	 * <p>A household is keyed on {@code (lastName, postcode)}: two owners are in the same
15	 * household when their normalized lastName and postcode match. The householdId is therefore
16	 * <em>deterministic</em> — the first 12 hex characters of SHA-256 over
17	 * {@code normalizedLastName + '|' + postcode} — so owners with the same lastName and
18	 * postcode share it automatically, with no lookup. lastName is normalized case-insensitively
19	 * with collapsed whitespace; the postcode is used as given (empty when absent).
20	 */
21	final class OwnerHousehold {
22	
23	    private OwnerHousehold() {
24	    }
25	
26	    /**
27	     * The deterministic householdId for the given lastName and postcode: the first 12 hex
28	     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners with the
29	     * same lastName and postcode therefore compute the same householdId automatically.
30	     */
31	    static String householdId(String lastName, String postcode) {
32	        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
33	        return Hashing.sha256Hex(input).substring(0, 12);
34	    }
35	
36	    /**
37	     * The number of owners in the given household — those whose {@code householdId} matches.
38	     * A {@code null} householdId matches nothing. Used by the household-keyed rules so the
39	     * membership comparison lives in the same place as the identity that defines it.
40	     */
41	    static int memberCount(String householdId, Iterable<Owner> owners) {
42	        if (householdId == null) {
43	            return 0;
44	        }
45	        int count = 0;
46	        for (Owner owner : owners) {
47	            if (householdId.equals(owner.getHouseholdId())) {
48	                count++;
49	            }
50	        }
51	        return count;
52	    }
53	
54	    /**
55	     * The highest {@code membershipLevel} among the existing owners in the given household —
56	     * those whose {@code householdId} matches — or {@code null} when the household has no
57	     * existing member with a level. A {@code null} householdId matches nothing. Used by the
58	     * level ceiling so a new owner cannot leapfrog their household's current maximum.
59	     */
60	    static Integer maxMembershipLevel(String householdId, Iterable<Owner> owners) {
61	        if (householdId == null) {
62	            return null;
63	        }
64	        Integer max = null;
65	        for (Owner owner : owners) {
66	            if (householdId.equals(owner.getHouseholdId())) {
67	                Integer level = owner.getMembershipLevel();
68	                if (level != null && (max == null || level > max)) {
69	                    max = level;
70	                }
71	            }
72	        }
73	        return max;
74	    }
75	
76	    /** Lower-case and collapse whitespace runs to a single space for comparison. */
77	    private static String normalize(String value) {
78	        if (value == null) {
79	            return "";
80	        }
81	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
82	    }
83	}
